{
  "name": "@neuralnomads/opencode-blender",
  "version": "0.4.6",
  "description": "OpenCode for Blender: lets OpenCode read and change an open Blender scene through an authenticated local host, with typed edits, inspection, verification renders and background renders.",
  "license": "MIT AND GPL-3.0-or-later",
  "type": "module",
  "keywords": [
    "opencode-integration",
    "opencode",
    "blender"
  ],
  "homepage": "https://github.com/NeuralNomadsAI/opencode-integrations/tree/main/integrations/blender/plugin",
  "repository": {
    "type": "git",
    "url": "https://github.com/NeuralNomadsAI/opencode-integrations",
    "directory": "integrations/blender/plugin"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "methods",
    "programs",
    "host",
    "README.md",
    "NOTICE.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "node scripts/build.ts",
    "build:host": "node scripts/build-host.ts",
    "typecheck": "tsc -p tsconfig.json"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.2.0 || ^0.0.0-dev"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode/plugin": "2.2.5",
    "esbuild": "0.28.2"
  },
  "opencodeIntegration": {
    "spec": 0,
    "id": "blender",
    "displayName": "OpenCode for Blender",
    "family": "native",
    "plugin": "neuralnomads.blender",
    "rpc": "neuralnomads.blender",
    "host": {
      "app": "blender",
      "protocol": 1,
      "range": "^0.4.6",
      "appVersions": ">=5.3",
      "payload": "host/blender/opencode_link-0.4.6.zip",
      "sha256": "c5defc03b74f70744899f16c02d95be76769582cf8f04d3fec75ff0efa7184ac"
    }
  }
}
